  return {rows, date: rows.map(r => r.date), o: rows.map(r => r.open ?? r.close), h: rows.map(r => r.high ?? r.close), l: rows.map(r => r.low ?? r.close), c: rows.map(r => r.close), v: rows.map(r => isNum(r.volume) ? r.volume : 1), custom: true};
