  const read = () => { SQ.sym = $('#sqSym').value; SQ.model = $('#sqModel').value; SQ.dist = $('#sqDist').value; SQ.lastN = parseInt($('#sqN').value, 10) || 0; SQ.h = Math.max(1, parseInt($('#sqH').value, 10) || 20); SQ.conf = +$('#sqConf').value; SQ.pos = +$('#sqPos').value || 1e6; };
