/* ======================= Bayesian ======================= */
const SQ_BAYES = [['ret', 'Return & risk (conjugate)'], ['capm', 'Bayesian CAPM / regression (Gibbs MCMC)'], ['cpd', 'Regime change-points (BOCPD)'], ['ar', 'Bayesian AR forecast']];
function sqBayes() {
  $('#sqBody').innerHTML = `<div class="card wide"><h2>Bayesian models</h2><div class="seg" id="sqBy" style="flex-wrap:wrap">${SQ_BAYES.map(([v, l]) => `<button data-v="${v}" aria-pressed="${SQ.bayes === v}">${l}</button>`).join('')}</div>
    ${sqCtl(sqField('Symbol', sqSymSel('sqSym', SQ.sym)) + sqField('Sample (last N days)', `<input id="sqN" value="${SQ.lastN}">`) + (SQ.bayes === 'capm' ? sqField('Market', sqSymSel('sqMkt', SQ.mkt || 'NEPSE')) + sqField('Errors', `<select id="sqErr"><option value="t">Student-t (robust to fat tails)</option><option value="normal">Normal</option></select>`) + sqField('Prior mean of β', `<input id="sqPb" value="1">`) + sqField('Prior sd of β', `<input id="sqPs" value="0.5">`) : '') + (SQ.bayes === 'cpd' ? sqField('Expected regime length (days)', `<input id="sqHz" value="250">`) : '') + (SQ.bayes === 'ar' ? sqField('AR order p', `<input id="sqP" value="2">`) + sqField('Horizon (days)', `<input id="sqH" value="20">`) : '') + (SQ.bayes === 'ret' ? sqField('Loss threshold (%)', `<input id="sqThr" value="-3">`) : ''))}
    <p class="sub" id="sqByNote"></p></div><div id="sqOut" style="display:grid;gap:18px"></div>`;
  $('#sqByNote').innerHTML = {ret: 'Normal–Inverse-Gamma conjugate model for daily returns: exact posterior of the mean and variance, the probability that the true mean return is positive, and a Student-t predictive distribution for tomorrow.', capm: 'Gibbs sampler (4 chains) for α and β with informative priors; Student-t errors via a scale-mixture make it robust to crash days. Convergence: split R̂ near 1.00 and large effective sample size (ESS).', cpd: 'Bayesian online change-point detection (Adams & MacKay 2007) with a Normal–Gamma model: at each day the posterior probability that a new regime (different mean and volatility) has just begun.', ar: 'AR(p) on daily returns estimated by Gibbs sampling; price paths are simulated from the posterior, so the fan chart includes parameter uncertainty.'}[SQ.bayes];
  seg('#sqBy', v => { SQ.bayes = v; sqBayes(); });
  $('#sqRun').onclick = () => { SQ.sym = $('#sqSym').value; SQ.lastN = parseInt($('#sqN').value, 10) || 0; sqTry(sqBayesRun); };
}
