  const mu = F.names.map((_, j) => ST.mean(F.rows.slice(0, ntr).map(r => r[j]))), sd = F.names.map((_, j) => ST.sd(F.rows.slice(0, ntr).map(r => r[j])) || 1), Z = F.rows.map(r => r.map((v, j) => (v - mu[j]) / sd[j]));
